content.content:
1	/* Override native GTK scrollbar colors for all web content.
2	 * Fixes the dark GTK trough painting near-black on hover under
3	 * Flat-Remix-GTK-Blue-Dark + prefer-dark. Explicit scrollbar-color
4	 * takes the GTK trough out of the equation, so hover can never
5	 * render black: track stays transparent, thumb is a neutral gray.
6	 * Thumb is deliberately bright/near-opaque with a faint tinted track
7	 * so the scrollbar reads clearly against dark page backgrounds. */
8	@-moz-document url-prefix("http") {
9	  * {
10	    scrollbar-color: rgba(190, 190, 190, 0.95) rgba(255, 255, 255, 0.08) !important;
11	    scrollbar-width: auto !important;
12	  }
13	}
14

